ee:message.ee:set-payload:
%dw 2.0
output application/json
var stockLevels = { "SKU-BOOK": 10, "SKU-MUG": 3, "SKU-EBOOK": 9999, "SKU-POSTER": 0 }
var unavailable = payload.items filter ((stockLevels[$.sku] default 0) < $.quantity) map $.sku
---
{ orderId: payload.orderId, available: isEmpty(unavailable), unavailableSkus: unavailable }
